'use strict';
// «Это не я» под сообщениями о безопасности (поток Т, задача Т4; пакет заказчика 13.11.2026, идея 9 списка «Идеи для Telegram-бота»).
// Раньше бот только советовал, что делать, если пароль сменил кто-то другой. Теперь под сообщением стоит кнопка: одно нажатие завершает все сеансы и закрывает вход.
// Кнопка есть под тремя сообщениями: «Пароль изменён» (в привязанный чат), «Привязан другой Telegram» и «Telegram отвязан» (оба — в прежний чат).
//   Под «Пароль сброшен» и «Вход заблокирован» её нет: пароль сбросил владелец или администратор платформы, а заблокированный вход уже закрыт.
// Что делает нажатие:
//   — завершает все сеансы учётной записи;
//   — закрывает вход тем же способом, что 10 неверных паролей подряд (pwLocked): открыть его может только новый пароль — сотруднику его выдаёт владелец организации
//     или администратор платформы, владельцу — администратор платформы; «Забыли пароль?» при закрытом входе код не присылает;
//   — отвязывает другой Telegram, привязанный вместо прежнего. Прежний чат обратно сам не привязывается: его привяжет владелец учётной записи после входа с новым паролем;
//   — отменяет ожидающий код замены Telegram и разовую привязку без кода после сброса пароля;
//   — пишет в историю учётной записи запись «через Telegram» и сообщает владельцам организации (о владельце — администраторам платформы), что нужно выдать новый пароль.
// У администратора платформы вход не закрывается — новый пароль ему выдать некому: кнопка завершает все его сеансы, пароль он меняет через «Забыли пароль?».
// Правила нажатия: кнопка действует 24 часа и только в том чате, куда пришло сообщение, — привязан ли этот чат сейчас, не важно (сообщение об отвязке приходит как раз в отвязанный чат);
//   право не нужно, выключатель «Действия из Telegram» на кнопку не влияет: это защита учётной записи, а не работа с данными организации.
//   Вход уже закрыт — «Кнопка устарела»; прошли сутки — бот советует попросить сброс пароля. Ответ бота — обычное сообщение: оно остаётся в переписке.
const TG_NOTME_H=24,TG_NOTME='Нажато «Это не я»';
// Вид сообщения: шаблон, тип в журнале «Телеграм», событие словами — для истории и сообщения владельцу
const TG_SEC={pass:['tgPassChanged','Пароль изменён','пароль изменён'],relink:['tgRelinked','Telegram отвязан','привязан другой Telegram'],unlink:['tgUnlinked','Telegram отвязан','Telegram отвязан']};
// Сообщения о безопасности, отправленные в макете: по логину, до перезагрузки страницы. chat — чат, куда ушло сообщение
const TG_SEC_MSGS={};
const tgSecOf=(u,chat)=>(TG_SEC_MSGS[u.login]||[]).filter(x=>x.chat===chat).map(x=>x.m);
// Сообщение о безопасности с кнопкой. kind: pass — пароль изменён, relink — привязан другой Telegram, unlink — Telegram отвязан; o.chat — прежний чат, o.tg — имя нового Telegram
function tgSecMsg(u,kind,o={}){const at=bishkekNow().hm,chat=o.chat||u.tg;
  return {t:tplFill(TG_SEC[kind][0],{логин:u.login,время:at,телеграм:o.tg||''}),at,btns:[[{t:tgBtnT('tgBtnNotMe','Это не я'),icon:'ban',act:'notMe',arg:{kind,chat,at:Date.now()}}]]}}
// Отправка: строка журнала «Телеграм» и сообщение в переписке макета. Чата нет — сообщения нет
function tgSecSend(u,kind,o={}){const chat=o.chat||u.tg;if(!chat)return null;
  tgSvc(u,TG_SEC[kind][1],o.chat?{chat}:{});const m=tgSecMsg(u,kind,o);(TG_SEC_MSGS[u.login]=TG_SEC_MSGS[u.login]||[]).push({chat,m});return m}
const tgNotMeWho=u=>accIsOwner(u)?'администратор платформы':'владелец организации';
// В макете кнопку нажимает тот, кто вошёл: его сеанс завершён — когда окно переписки закроют, макет покажет страницу входа
let TG_SEC_OUT='';
function tgSecLeave(){const l=TG_SEC_OUT;if(!l)return;TG_SEC_OUT='';
  if(DEMO.on)return toast('В демо-версии страницы входа нет: в работе вы бы вышли из программы','lock');
  MODALS.slice().forEach(m=>m.close());S.loggedIn=false;showLogin('login',{login:l});toast('Все сеансы завершены: войдите заново','lock')}
tgAct('notMe',{prev:true,stale:u=>u.id!=='admin'&&!!u.pwLocked,
  run:(u,a,m,b)=>{
    if(Date.now()-a.at>TG_NOTME_H*3600e3)return {eph:tplFill('tgActNotMeLate',{часов:TG_NOTME_H})};
    const adm=u.id==='admin',own=!adm&&accIsOwner(u),org=adm?'':accOrg(u),ev=TG_SEC[a.kind][2];
    const n=accEndSessions(u.login,'Завершён: «Это не я» из Telegram');
    // Другой Telegram отвязан; прежний чат остаётся «прежним»: тот же чат потом привязывается без кода, любой другой — только кодом из него
    const cut=!!u.tg&&u.tg!==a.chat;if(cut){tgSvc(u,'Telegram отвязан');u.tg=null;u.tgPrev=a.chat}
    if(typeof RL==='object'&&RL[u.login])RL[u.login].code=null;delete u.tgFree;
    if(!adm){u.pwLocked=nowStamp();u.pwLockWhy='notme'}
    const what=`${adm?'Все сеансы завершены':'Вход закрыт'} кнопкой «Это не я» под сообщением бота «${ev}»${n?`, завершено сеансов: ${n}`:''}${cut?', другой Telegram отвязан':''}`;
    tgLog('acc',u.login,what);if(EMP.includes(u))tgLog('emp',u.id,what);
    // Ответ бота — в тот же чат; владельцам организации — «выдайте сотруднику новый пароль», администраторам платформы — то же о владельце (в макете — строки журнала «Телеграм»)
    tgSvc(tgOf(u),TG_NOTME,{chat:a.chat,org});if(!adm)(own?leadAdmins():accOwners(u)).forEach(w=>tgSvc(tgOf(w),TG_NOTME,{org:own?'':org}));
    TG_SEC_OUT=u.login;b.icon='';
    return {done:adm?'✓ Сеансы завершены':'✓ Вход закрыт',msg:{t:tplFill(adm?'tgNotMeAdmin':'tgNotMeDone',{логин:u.login,кто:tgNotMeWho(u)}),at:bishkekNow().hm}}}});
// Окно «прежний чат»: сообщения бота в чате, который отвязали от учётной записи («Мой профиль» → «Демо: прежний чат»)
function tgPrevDlg(u,done){const chat=u.tgPrev,L=[{day:'Сегодня'},...tgSecOf(u,chat)];
  tgBotDlg(u,L,{who:'Прежний чат '+chat,title:'Прототип: прежний чат',sub:'Сообщения бота в чате, который отвязали от учётной записи',onClose:()=>{if(S.loggedIn&&done)done()},
    note:'Это макет. Кнопка «Это не я» действует 24 часа и только в том чате, куда пришло сообщение: она завершает все сеансы и закрывает вход, пока владелец организации не выдаст новый пароль.'})}
// Сообщение о смене пароля сразу после смены в «Мой профиль»
function tgPassDlg(u){const L=tgSecOf(u,u.tg).slice(-1);if(!L.length)return;
  tgBotDlg(u,L,{sub:'Бот сообщил о смене пароля в '+u.tg,
    note:'Это макет. Если пароль меняли не вы, нажмите «Это не я»: все сеансы завершатся, а вход закроется, пока владелец организации (владельцу — администратор платформы) не выдаст новый пароль.'})}
